import { _decorator, Button, Component, Label, Node, tween, Tween, Vec3 } from "cc";
import StoreManager from "../store/StoreManager";
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from "../events/GameRuntimeEventBus";

const { ccclass, property } = _decorator;

@ccclass("1002/gs002/BuyFeaturePopupView")
export class BuyFeaturePopupView extends Component {

    @property(Node)
    popup: Node = null!;

    @property(Label)
    prizeLabel: Label = null!;

    @property(Label)
    prizeLabel2: Label = null!;

    @property(Label)
    betLabel: Label = null!;

    @property(Button)
    buyBtn: Button = null!;

    @property(Button)
    buyBtn2: Button = null!;

    @property(Button)
    closeBtn: Button = null!;

    @property(Button)
    minusBtn: Button = null!;

    @property(Button)
    plusBtn: Button = null!;

    @property(Node)
    mask: Node = null!;

    private disposers: Array<() => void> = [];
    private mult1 = 0;
    private mult2 = 0;

    protected override onLoad(): void {
        this.buyBtn.node.on(Button.EventType.CLICK, () => this.onBuy(), this);
        this.buyBtn2.node.on(Button.EventType.CLICK, () => this.onBuy(), this);
        this.closeBtn.node.on(Button.EventType.CLICK, this.onCancel, this);
        this.minusBtn.node.on(Button.EventType.CLICK, this.onMinus, this);
        this.plusBtn.node.on(Button.EventType.CLICK, this.onPlus, this);
        this.mask?.on(Node.EventType.TOUCH_END, this.onCancel, this);

        const gameStore = StoreManager.getInstance().getGameStore();
        // mobx 移除計劃：SlotGameStore.buyFeatureData/buyFeatureCloseRequested/
        // TemplateStore.betBalance 已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this.disposers.push(gameRuntimeEventBus.on(GAME_EVENT_TYPE.BUY_FEATURE_DATA_CHANGED, (e) => { if (e.data) this.show(e.data); }));
        this.disposers.push(gameRuntimeEventBus.on(GAME_EVENT_TYPE.BUY_FEATURE_CLOSE_CHANGED, (e) => { if (e.requested) this.close(); }));
        this.disposers.push(gameRuntimeEventBus.on(GAME_EVENT_TYPE.BET_BALANCE_CHANGED, () => this.refresh()));

        const data = gameStore.buyFeatureData;
        if (data) this.show(data);
    }

    private show(data: { prefix: string; amount: string; mult: number }): void {
        this.mult1 = data.mult;
        this.mult2 = data.mult;
        this.refresh();
        this.playEnter();
    }

    private refresh(): void {
        const store = StoreManager.getInstance();
        const bet = store.getModel("TemplateStore").betBalance;
        const format = store.getGameStore().formatAmount;
        this.betLabel.string = format(bet);
        this.prizeLabel.string = format(bet * this.mult1);
        this.prizeLabel2.string = format(bet * this.mult2);
    }

    private playEnter(): void {
        const n = this.popup;
        Tween.stopAllByTarget(n);
        n.setScale(0, 0, 1);
        tween(n)
            .to(0.166, { scale: new Vec3(1.2, 1.2, 1) }, { easing: "sineInOut" })
            .to(0.167, { scale: new Vec3(0.95, 0.95, 1) }, { easing: "sineInOut" })
            .to(0.167, { scale: new Vec3(1, 1, 1) }, { easing: "sineInOut" })
            .start();
    }

    private close(): void {
        const n = this.popup;
        Tween.stopAllByTarget(n);
        tween(n)
            .to(0.166, { scale: new Vec3(1.05, 1.05, 1) }, { easing: "sineInOut" })
            .to(0.167, { scale: new Vec3(0, 0, 1) }, { easing: "sineInOut" })
            .call(() => { if (this.node?.isValid) StoreManager.getInstance().getGameStore().completeBuyFeatureClose(); })
            .start();
    }

    private onBuy(): void { StoreManager.getInstance().getGameStore().fireBuyFeatureConfirm(); }
    private onCancel(): void { StoreManager.getInstance().getGameStore().fireBuyFeatureCancel(); }
    private onMinus(): void { StoreManager.getInstance().getModel("TemplateStore").minusBetLevel(); }
    private onPlus(): void { StoreManager.getInstance().getModel("TemplateStore").addBetLevel(); }

    protected override onDestroy(): void {
        this.disposers.forEach(d => d());
        this.disposers = [];
        if (this.popup) Tween.stopAllByTarget(this.popup);
    }
}
