import { _decorator, Node, Sprite, SpriteFrame, sp, tween, Tween, type TweenEasing, UITransform, Vec3 } from "cc";
import { ReelView } from "./ReelView";
import { NgSymbol } from "./NgSymbol";

const { ccclass } = _decorator;

@ccclass("1002/ReelView_1002")
export class ReelView_1002 extends ReelView {
    public symbolSpines: sp.Skeleton[] = [];
    private currentSymbolNames: (string | null)[] = [];

    // 只在初始盤定位(tumbleFill)期間放行倍數符號打雷;cascade 消除掉落(cascadeFill)不重播
    private allowSettleLightning: boolean = false;

    private coinDisplays: (NgSymbol | null)[] = [];

    public override strip: number[] = [2, 2, 2, 5, 6, 7, 8, 9, 10, 11, 12, 14, 15, 16];

    public spinBet: number = 0;
    private static readonly COIN_MULTIPLIERS = [0.4, 0.6, 0.8, 1, 2, 3, 5, 8, 10, 20];

    private spriteHolders: (Node | null)[] = [];
    private spriteHolderSprites: (Sprite | null)[] = [];
    private spriteHolderUIs: (UITransform | null)[] = [];

    private static applySymbolVisual(ui: UITransform, frame: SpriteFrame | null): void {
        if (!frame) return;
        const parent = ui.node.parent;
        const parentUI = parent?.getComponent(UITransform);
        if (!parentUI) return;
        const parentW = parentUI.contentSize.width;
        const parentH = parentUI.contentSize.height;
        const orig = frame.originalSize;
        const scale = Math.min(parentW / orig.width, parentH / orig.height);
        ui.setContentSize(orig.width * scale, orig.height * scale);
    }

    /** strip index → 預設金額，finalRng 可見位置放正確值，其餘放隨機值 */
    private stripCoinAmounts: Map<number, string> = new Map();

    /** 各 symbol 的 idle/stop 動畫名 */
    private static readonly SPINE_STOP_ANIM: Record<string, string> = {
        "h2": "h2stop",
        "h3": "h3stop",
        "h4": "h4stop",
        "h5": "h5stop",
        "n1": "n1stop",
        "n2": "n2stop",
        "n3": "n3stop",
        "n4": "n4stop",
        "n5": "n5stop",
        "h1": "Godstop",
        "w1": "WILDstop",
        "b1": "redcoin_stop",
        "b2": "greencoin_stop",
        "b3": "bluecoin_stop",
    };

    /** 各 symbol 的 win 動畫名（中獎時播） */
    private static readonly SPINE_WIN_ANIM: Record<string, string> = {
        "h2": "h2",
        "h3": "h3",
        "h4": "h4",
        "h5": "h5",
        "n1": "n1",
        "n2": "n2",
        "n3": "n3",
        "n4": "n4",
        "n5": "n5",
        "h1": "God",
        "w1": "WILD",
        "b1": "redcoin",
        "b2": "greencoin",
        "b3": "bluecoin",
    };

    private static readonly SYMBOL_NAME_MAP: Record<string, string> = {
        "fu": "w1",
        "caishen": "h1",
        "jin_chan": "h2",
        "wealth_tree": "h3",
        "golden_carp": "h4",
        "golden_ruyi": "h5",
        "a": "n1",
        "k": "n2",
        "q": "n3",
        "j": "n4",
        "ten": "n5",
        "red_coin": "b1",
        "green_coin": "b2",
        "blue_coin": "b3",
    };

    protected override getSymbolNameMap(): Record<string, string> {
        return ReelView_1002.SYMBOL_NAME_MAP;
    }

    protected override onSymbolCreated(symbol: Node, _symbolIdx: number): void {
        this.currentSymbolNames.push(null);

        const holder = symbol.getChildByName("spriteFrame") ?? symbol.getChildByName("visual")?.getChildByName("spriteFrame");
        this.spriteHolders.push(holder);
        this.spriteHolderSprites.push(holder?.getComponent(Sprite) ?? null);
        this.spriteHolderUIs.push(holder?.getComponent(UITransform) ?? null);
        holder?.setScale(1, 1, 1);

        const coinDisplay = symbol.getComponent(NgSymbol);
        this.coinDisplays.push(coinDisplay);
        if (coinDisplay) coinDisplay.hide();
    }

    /** DebugPanel「Symbol 縮放」呼叫，套用到這個 reel 目前所有的 symbol cell */
    setSymbolScale(scale: number): void {
        for (const ng of this.coinDisplays) ng?.setScaleMultiplier(scale);
    }

    protected override onSymbolStepIntoTop(symbolIdx: number, stripIdx: number, frameIdx: number): void {
        if (this.isSpinning && this.spinBet > 0 && this.isCoinFrame(frameIdx)) {
            const amount = this.stripCoinAmounts.get(stripIdx) ?? this.randomCoinAmount();
            this.coinDisplays[symbolIdx]?.show(amount);
        }
    }

    override setSymbolDisplay(symbolIdx: number, stripIdx: number): void {
        const frame = this.spriteFrames[stripIdx];
        // 倖存倍率球掉落：該格 symbol_m 已 active（上一次 applyMultiplierLabels 開的），保留動畫球 + 既有數字，
        // 不切回靜態圖，否則 cascade 掉落途中倍率數字會消失、落定才又出現
        if (frame?.name?.startsWith("symbol_m") && this.coinDisplays[symbolIdx]?.isMultiplierBallActive()) {
            this.currentSymbolNames[symbolIdx] = frame?.name || null;
            return;
        }
        this.coinDisplays[symbolIdx]?.hide();
        this.coinDisplays[symbolIdx]?.hideMultiplierBall();   // 貼任何符號先關 symbol_m，避免 idle/進場/buffer 的 symbol_m frame 殘留亂閃
        this.coinDisplays[symbolIdx]?.hideScatter();
        this.currentSymbolNames[symbolIdx] = frame?.name || null;

        const holderSprite = this.spriteHolderSprites[symbolIdx];
        if (holderSprite) {
            holderSprite.enabled = true;
            holderSprite.spriteFrame = frame;
        }

        if (frame?.name === "symbol_scatter") {
            this.coinDisplays[symbolIdx]?.showScatter();
            if (holderSprite) holderSprite.enabled = false;
        }

        const ui = this.spriteHolderUIs[symbolIdx];
        if (ui) {
            ReelView_1002.applySymbolVisual(ui, frame);
        }
    }

    protected override onSymbolSettled(symbolIdx: number): void {
        if (!this.allowSettleLightning) return;
        const name = this.currentSymbolNames[symbolIdx];
        const posIdx = this.posIndexes[symbolIdx];
        if (name?.startsWith("symbol_m") && posIdx >= 2 && posIdx <= 6) {
            this.coinDisplays[symbolIdx]?.playUp(name);
        }
    }

    playWinAnim(row: number, _animName: string, loop: boolean = true, onComplete?: () => void): boolean {
        const posIdx = row + 2;
        for (let i = 0; i < this.symbolNodes.length; i++) {
            if (this.posIndexes[i] !== posIdx) continue;
            const spine = this.symbolSpines[i];
            const frameName = this.currentSymbolNames[i];
            if (!spine || !frameName) return false;
            const winAnim = ReelView_1002.SPINE_WIN_ANIM[frameName];
            if (!winAnim) return false;
            try {
                spine.setAnimation(0, winAnim, loop);
                if (onComplete) {
                    spine.setCompleteListener((entry) => {
                        if (entry.trackIndex === 0) {
                            spine.setCompleteListener(null);
                            onComplete();
                        }
                    });
                }
                return true;
            } catch (e) {
                return false;
            }
        }
        return false;
    }

    /** 消除爆破：有 symbol_frame 特效的格子播 spine 取代縮小 tween；timeScale 隨三段速的 explode 時長縮放 */
    private static readonly ELIMINATE_BASE_TIME = 0.3;

    override async explode(rows: number[], explodeTime: number): Promise<void> {
        const fxRows: number[] = [];
        const tasks: Promise<void>[] = [];
        const speed = ReelView_1002.ELIMINATE_BASE_TIME / Math.max(explodeTime, 0.05);
        for (const row of rows) {
            const idx = this.findSymbolNodeAtPosIndex(row + 2);
            const ng = idx >= 0 ? this.coinDisplays[idx] : null;
            if (ng?.hasEliminateFx()) {
                fxRows.push(row);
                tasks.push(ng.playEliminate(speed));
            }
        }
        const rest = rows.filter(r => !fxRows.includes(r));
        await Promise.all([
            ...tasks,
            rest.length ? super.explode(rest, explodeTime) : Promise.resolve(),
        ]);
        if (fxRows.length) await super.explode(fxRows, 0);
    }

    /** 中獎符號爆炸前,對指定 row 的符號各播一次中獎演出(symbol_win;低價符號再疊 symbol_l)；
     *  timeScale 隨三段速的 winFx 時長縮放（同 explode 的做法） */
    private static readonly WIN_FX_BASE_TIME = 1.6;

    playWinFx(rows: number[], winFxTime = ReelView_1002.WIN_FX_BASE_TIME): Promise<void> {
        const speed = ReelView_1002.WIN_FX_BASE_TIME / Math.max(winFxTime, 0.05);
        const promises: Promise<void>[] = [];
        for (const row of rows) {
            const idx = this.findSymbolNodeAtPosIndex(row + 2);
            if (idx < 0) continue;
            const ng = this.coinDisplays[idx];
            if (ng) promises.push(ng.playWin(this.currentSymbolNames[idx] ?? undefined, speed));
        }
        return Promise.all(promises).then(() => undefined);
    }

    stopAllWinAnims(): void {
        for (let i = 0; i < this.symbolNodes.length; i++) {
            const spine = this.symbolSpines[i];
            const frameName = this.currentSymbolNames[i];
            if (!spine || !frameName) continue;
            const stopAnim = ReelView_1002.SPINE_STOP_ANIM[frameName];
            if (stopAnim) {
                try { spine.setAnimation(0, stopAnim, false); } catch (e) { }
            }
        }
    }

    /** 停輪後顯示 coin 金額（只對 coin symbol 生效） */
    showCoinInfo(row: number, amount: string): void {
        const posIdx = row + 2;
        for (let i = 0; i < this.symbolNodes.length; i++) {
            if (this.posIndexes[i] !== posIdx) continue;
            const frameName = this.currentSymbolNames[i];
            if (!frameName || !this.isCoinFrameName(frameName)) break;
            this.coinDisplays[i]?.show(amount);
            break;
        }
    }

    /** 設定停輪時的 coin 金額：finalRng 可見位置用正確值，其餘 coin 位置用隨機值 */
    prepareStopCoinAmounts(finalRng: number, coinInfos: { row: number; amount: string }[]): void {
        this.stripCoinAmounts.clear();
        if (this.spinBet <= 0) return;

        const correctMap = new Map<number, string>();
        for (const info of coinInfos) correctMap.set(info.row, info.amount);

        for (let i = 0; i < this.strip.length; i++) {
            if (!this.isCoinFrame(this.strip[i])) continue;
            const row = (i - finalRng - 2 + this.strip.length * 2) % this.strip.length;
            if (row < 3 && correctMap.has(row)) {
                this.stripCoinAmounts.set(i, correctMap.get(row)!);
            } else {
                this.stripCoinAmounts.set(i, this.randomCoinAmount());
            }
        }
    }

    clearStopCoinAmounts(): void {
        this.stripCoinAmounts.clear();
    }

    clearAllCoinInfo(): void {
        for (const cd of this.coinDisplays) {
            cd?.hide();
        }
    }

    /** 倍率球：row=可見列(0..4 top-down)，value=null 隱藏球+數字；否則播 symbol_m 球(side/tier)+常駐數字 */
    setMultiplierLabel(row: number, value: number | null, side: number = 1, tier: number = 4): void {
        const idx = this.findSymbolNodeAtPosIndex(row + 2);
        if (idx < 0) return;
        const ng = this.coinDisplays[idx];
        if (!ng) return;
        if (value == null) {
            ng.hideMultiplierBall();
            ng.hide();
        } else {
            ng.showMultiplierBall(side, tier);
            ng.showMultiplier(value);
        }
    }

    playMultiplierUpgrade(row: number, side: number, newTier: number, newValue: number): void {
        const idx = this.findSymbolNodeAtPosIndex(row + 2);
        if (idx < 0) return;
        this.coinDisplays[idx]?.playMul(side, newTier, newValue);
    }

    playMultiplierCollect(row: number): void {
        const idx = this.findSymbolNodeAtPosIndex(row + 2);
        if (idx < 0) return;
        this.coinDisplays[idx]?.playCollect();
    }

    playScatterWin(row: number): void {
        const idx = this.findSymbolNodeAtPosIndex(row + 2);
        if (idx < 0) return;
        this.coinDisplays[idx]?.playScatterWin();
    }

    private isCoinFrame(stripIdx: number): boolean {
        const name = this.spriteFrames[stripIdx]?.name ?? "";
        return this.isCoinFrameName(name);
    }

    private isCoinFrameName(name: string): boolean {
        return name === "b1" || name === "b2" || name === "b3";
    }

    private randomCoinAmount(): string {
        const mults = ReelView_1002.COIN_MULTIPLIERS;
        const mult = mults[Math.floor(Math.random() * mults.length)];
        return String(this.spinBet * mult);
    }

    getCellWorldPosition(posIdx: number): Vec3 {
        return this.posList[posIdx].getWorldPosition();
    }

    override async tumbleClear(clearTime: number, rowDelay: number = 0.05, clearEase: TweenEasing = 'quadIn'): Promise<void> {
        const promises: Promise<void>[] = [];
        const dropOrder = [6, 5, 4, 3, 2];

        const cellHeight = this.posList[1].position.y - this.posList[2].position.y;
        const boardHeight = cellHeight * 5;
        // 物理式掉落：整批同樣掉出 boardHeight 這段距離，用重力反推的耗時取代固定 clearTime，
        // 每行仍保留原本的漸快 stagger 手感（0.75 + i*0.125）疊在物理耗時之上。
        const physicsClearTime = this.physicsFallDuration(boardHeight, this.cellHeightAbs(), clearTime);

        for (let i = 0; i < dropOrder.length; i++) {
            const posIdx = dropOrder[i];
            const symIdx = this.findSymbolNodeAtPosIndex(posIdx);
            if (symIdx < 0) continue;
            const node = this.symbolNodes[symIdx];
            const opacity = this.symbolOpacities[symIdx];
            const targetY = this.posList[posIdx].position.y - boardHeight;

            const rowClearTime = physicsClearTime * (0.75 + i * 0.125);

            promises.push(new Promise<void>(resolve => {
                Tween.stopAllByTarget(node);
                tween(node)
                    .delay(i * rowDelay)
                    .to(rowClearTime, { position: new Vec3(0, targetY, 0) }, { easing: clearEase })
                    .call(() => {
                        opacity.opacity = 0;
                        resolve();
                    })
                    .start();
            }));
        }
        await Promise.all(promises);
    }

    /** 落地果凍效果（squash）的關鍵影格：scale 是每格相對 (1,1) 的目標值，intensity=1 時為原始美術數值（跟 1001 對齊） */
    private static readonly SQUASH_KEYFRAMES: { time: number; scale: [number, number]; easing: TweenEasing }[] = [
        { time: 0.11, scale: [1.45, 0.66], easing: 'quadOut' },
        { time: 0.12, scale: [0.8, 1.25], easing: 'quadOut' },
        { time: 0.08, scale: [1.25, 0.8], easing: 'quadOut' },
        { time: 0.09, scale: [0.9, 1.12], easing: 'quadOut' },
        { time: 0.08, scale: [1, 1], easing: 'sineOut' },
    ];

    /** DebugPanel「果凍效果」滑桿：0=關閉、1=原始美術數值、可調更誇張，下次 spin 生效；預設 1（跟 1001 現行值對齊） */
    private squashIntensity: number = 1;

    setSquashIntensity(intensity: number): void {
        this.squashIntensity = intensity;
    }

    private landingSquash(t: Tween<Node>): Tween<Node> {
        if (this.squashIntensity <= 0) return t;
        for (const kf of ReelView_1002.SQUASH_KEYFRAMES) {
            const sx = 1 + (kf.scale[0] - 1) * this.squashIntensity;
            const sy = 1 + (kf.scale[1] - 1) * this.squashIntensity;
            t = t.to(kf.time, { scale: new Vec3(sx, sy, 1) }, { easing: kf.easing });
        }
        return t;
    }

    override async tumbleFill(newSymbolNames: string[], fillTime: number, rowDelay: number = 0.05, _onFirstLanded?: () => void, fillEase: TweenEasing = 'quadIn'): Promise<void> {
        // onSymbolSettled 在落定 tween 的 .call 同步觸發(仍在此 await 內),放行窗口涵蓋整個初始盤落定
        this.allowSettleLightning = true;
        const cellHeight = this.posList[1].position.y - this.posList[2].position.y;
        const startY = this.posList[0].position.y + cellHeight * 2;
        const promises: Promise<void>[] = [];
        const fillOrder = [6, 5, 4, 3, 2];

        for (let i = 0; i < fillOrder.length; i++) {
            const posIdx = fillOrder[i];
            const symIdx = this.findSymbolNodeAtPosIndex(posIdx);
            if (symIdx < 0) continue;

            const nameIdx = fillOrder.length - 1 - i;
            const srcName = newSymbolNames[nameIdx];
            const imgName = ReelView_1002.SYMBOL_NAME_MAP[srcName] ?? srcName;
            let frameIdx = -1;
            for (let j = 0; j < this.spriteFrames.length; j++) {
                if (this.spriteFrames[j]?.name === imgName) { frameIdx = j; break; }
            }
            if (frameIdx < 0) {
                console.warn(`[tumbleFill] no spriteFrame for name="${imgName}" (src="${srcName}"), sprite frames:`,
                    this.spriteFrames.map(f => f?.name));
                frameIdx = 0;
            }

            const targetY = this.posList[posIdx].position.y;

            this.setSymbolDisplay(symIdx, frameIdx);
            this.symbolOpacities[symIdx].opacity = 255;
            this.symbolNodes[symIdx].setScale(1, 1, 1);
            this.symbolNodes[symIdx].setPosition(0, startY, 0);

            const node = this.symbolNodes[symIdx];
            // 物理式掉落：各行從同一個 startY 落到各自的 targetY，落下距離不同（越下面的格子
            // 掉得越遠），用重力反推耗時取代所有行套同一個固定 fillTime；落地前加一小段
            // 落地彈跳（appendLandingBounce）。
            const cellHeightAbs = this.cellHeightAbs();
            const physicsFillTime = this.physicsFallDuration(targetY - startY, cellHeightAbs, fillTime);
            promises.push(new Promise<void>(resolve => {
                Tween.stopAllByTarget(node);
                this.landingSquash(this.appendLandingBounce(
                    tween(node)
                        .delay(i * rowDelay)
                        .to(physicsFillTime, { position: new Vec3(0, targetY, 0) }, { easing: fillEase }),
                    targetY,
                    cellHeightAbs
                )).call(() => { this.onSymbolSettled(symIdx); resolve(); }).start();
            }));
        }
        await Promise.all(promises);
        this.allowSettleLightning = false;
    }
}
