// ==================== Spin API Response ====================

export interface SpinResponse {
    code: number;
    time: number;
    message: string;
    data: SpinData;
}

export interface SpinData {
    slots: SlotsData;
    machine_info: MachineInfo;
    stack_result: any[];
    balance: string;
    cr: any;
}

export interface SlotsData {
    icon_table: IconTableItem[];
    icon_indexes: number[];
    hold_and_spin: HoldAndSpin;
    reels: ReelPanel[];
    achieves: AchieveItem[];
    rewards: Record<string, Record<string, number>>;
    is_free: boolean;
    seed: number;
    multiple: number;
    current_feature: number;
    cr_result: boolean;
    cr_pre: any;
    machine_id: string;
    currency: string;
    bet: string;
}

export interface IconTableItem {
    symbol: string;
    multi: string;
    amount: string;
    col: number;
    row: number;
    type: "normal" | "prosperity" | "double" | "longevity";
}

export interface HoldAndSpin {
    double: number;
    longevity: number;
    prosperity: number;
    double_max?: boolean;
    longevity_max?: boolean;
    prosperity_max?: boolean;
}

export interface ReelPanel {
    grid: GridItem[];
    grand: string;
    mutil: string;
    amount: string;
}

export interface GridItem {
    left: number;
    coin_list: Record<string, CoinItem>;
}

export interface CoinItem {
    symbol: string;
    current_multi: string;
    multi: string;
    current_amount: string;
    amount: string;
}

export interface AchieveItem {
    feature: number;
    win: number | string;
    type: "line" | "respin";
    length?: number;
    icon?: string;
    line?: string;
    left?: number;
    param?: boolean;
    order?: number;
    origin_line?: string;
    amount: number;
    multiple: number;
    total_coin?: number;
}

// ==================== Config API Response ====================

export interface ConfigResponse {
    code: number;
    time: number;
    message: string;
    data: ConfigData;
}

export interface ConfigData {
    base: BaseConfig;
    client_config: any;
}

export interface BaseConfig {
    column: number;
    shape: string[];
    icon_matrix: string[][];
}

// ==================== Init API Response ====================

export interface InitResponse {
    code: number;
    time: number;
    message: string;
    data: InitData;
}

export interface InitData {
    game: GameInfo;
    machine_info: InitMachineInfo;
}

export interface GameInfo {
    balance: string;
    balance_name: string;
    user_id: string;
    machine_name: string;
    currency: string;
    auth_key: string;
    platform: string;
    use_last_bet: any;
}

export interface InitMachineInfo {
    extra: HoldAndSpin;
    bet_level: number[];
    bet: number;
    spin_total_win: string;
    icon_table: IconTableItem[] | null;
    icon_indexes: number[] | null;
}

export interface MachineInfo {
    extra: HoldAndSpin;
    spin_total_win: number | string;
}

// ==================== History API Response ====================

export interface HistoryResponse {
    code: number;
    time: number;
    message: string;
    data: HistoryItem[];
}

export interface HistoryItem {
    round_id: string;
    currency: number;
    bet: string;
    win: string;
    balance: string;
    created_at: number;
}
